const uploads = $input.all().map((item) => {
  const data = item && typeof item.json === "object" && item.json !== null
    ? item.json
    : {};
  return data;
});

if (uploads.length < 2) {
  throw new Error("Expected two Cloudinary upload items.");
}

const textValue = (item, key) => {
  const value = item[key];
  return value == null ? "" : String(value).toLowerCase();
};

const isTexUpload = (item) => {
  const publicId = textValue(item, "public_id");
  const secureUrl = textValue(item, "secure_url");
  const url = textValue(item, "url");

  return (
    publicId.endsWith(".tex") ||
    secureUrl.endsWith(".tex") ||
    url.endsWith(".tex")
  );
};

const isPdfUpload = (item) => {
  const fileFormat = textValue(item, "format");
  const publicId = textValue(item, "public_id");
  const secureUrl = textValue(item, "secure_url");
  const url = textValue(item, "url");

  return (
    fileFormat === "pdf" ||
    publicId.endsWith(".pdf") ||
    secureUrl.endsWith(".pdf") ||
    url.endsWith(".pdf")
  );
};

const texUpload = uploads.find(isTexUpload);
const pdfUpload = uploads.find(isPdfUpload);

if (!texUpload) {
  throw new Error("Could not identify the TEX upload result.");
}

if (!pdfUpload) {
  throw new Error("Could not identify the PDF upload result.");
}

const texUrl = texUpload.secure_url || texUpload.url;
const pdfUrl = pdfUpload.secure_url || pdfUpload.url;

if (!texUrl || !pdfUrl) {
  throw new Error("Cloudinary did not return both TEX and PDF URLs.");
}

const source = $("Normalize Input").first().json;

return [
  {
    json: {
      document_type: source.document_type,
      application_id: source.application_id,
      job_id: source.job_id,
      company_name: source.company_name,
      job_title: source.job_title,
      tex_url: texUrl,
      pdf_url: pdfUrl,
      tex_public_id: texUpload.public_id,
      pdf_public_id: pdfUpload.public_id,
    },
  },
];

const rows = $input.all().map((item) => item.json);
const config = {};
const seen = new Set();

for (const row of rows) {
  const key = String(row.configKey ?? '').trim();
  if (!key) throw new Error('Configuration row is missing configKey.');
  if (seen.has(key)) throw new Error(`Duplicate configuration key: ${key}`);
  seen.add(key);
  if (row.enabled === false || String(row.enabled).toLowerCase() === 'false') continue;

  const type = String(row.valueType ?? 'text').trim().toLowerCase();
  const raw = row.value;
  if (type === 'number') {
    const value = Number(raw);
    if (!Number.isFinite(value)) throw new Error(`Configuration ${key} must be a number.`);
    config[key] = value;
  } else if (type === 'boolean') {
    if (typeof raw === 'boolean') config[key] = raw;
    else if (String(raw).toLowerCase() === 'true') config[key] = true;
    else if (String(raw).toLowerCase() === 'false') config[key] = false;
    else throw new Error(`Configuration ${key} must be true or false.`);
  } else if (type === 'json') {
    try { config[key] = typeof raw === 'string' ? JSON.parse(raw) : raw; }
    catch (error) { throw new Error(`Configuration ${key} contains invalid JSON: ${error.message}`); }
  } else if (type === 'text') {
    config[key] = String(raw ?? '');
  } else {
    throw new Error(`Unsupported valueType "${type}" for configuration ${key}.`);
  }
}

const required = ["tenant_key","tenant_enabled","document_worker_url","cloudinary_folder_prefix","cloudinary_tags"];
const missing = required.filter((key) => config[key] === undefined || config[key] === null || config[key] === '');
if (missing.length) throw new Error(`Missing enabled configuration values: ${missing.join(', ')}`);

let source;
try { source = $('Configuration Input').first(); } catch (error) {}
if (!source) throw new Error('Could not resolve the workflow input before configuration loading.');

return [{
  json: {
    ...source.json,
    config,
    project_selection_count: config.project_selection_count,
    work_experience_selection_count: config.work_experience_selection_count,
  },
  binary: source.binary,
  pairedItem: { item: 0 },
}];
